installer-gui-script.script:
var rokid = {
  version: 'ROKID_VERSION',
  arch: 'ROKID_ARCH',
  minOS: 'ROKID_MIN_OS',
  installedVersion: '/Library/Application Support/RokidCoder/installed-version'
};

function rokidNumbers(text) {
  return String(text).split('.').map(function (part) { return parseInt(part, 10) || 0; });
}

function rokidCompareNumbers(a, b) {
  for (var i = 0; i < Math.max(a.length, b.length); i++) {
    var x = a[i] || 0, y = b[i] || 0;
    if (x !== y) return x < y ? -1 : 1;
  }
  return 0;
}

// Semantic version order: 1.0.0-test.1 < 1.0.0-test.2 < 1.0.0 < 1.0.1.
function rokidCompareVersions(a, b) {
  var pa = String(a).split('-'), pb = String(b).split('-');
  var core = rokidCompareNumbers(rokidNumbers(pa.shift()), rokidNumbers(pb.shift()));
  if (core !== 0) return core;
  var ra = pa.join('-'), rb = pb.join('-');
  if (ra === rb) return 0;
  if (ra === '') return 1;
  if (rb === '') return -1;
  var ia = ra.split('.'), ib = rb.split('.');
  for (var i = 0; i < Math.max(ia.length, ib.length); i++) {
    if (ia[i] === undefined) return -1;
    if (ib[i] === undefined) return 1;
    var na = /^\d+$/.test(ia[i]), nb = /^\d+$/.test(ib[i]);
    if (na && nb) {
      var d = parseInt(ia[i], 10) - parseInt(ib[i], 10);
      if (d !== 0) return d < 0 ? -1 : 1;
    } else if (na !== nb) {
      return na ? -1 : 1;
    } else if (ia[i] !== ib[i]) {
      return ia[i] < ib[i] ? -1 : 1;
    }
  }
  return 0;
}

function rokidRefuse(message) {
  my.result.title = 'Rokid Coder can’t be installed';
  my.result.message = message;
  my.result.type = 'Fatal';
  return false;
}

function rokidInstallationCheck() {
  if (rokidCompareNumbers(rokidNumbers(system.version.ProductVersion), rokidNumbers(rokid.minOS)) < 0) {
    return rokidRefuse('Rokid Coder needs macOS ' + rokid.minOS.replace(/(\.0)+$/, '') + ' or later — update in System Settings > General > Software Update');
  }
  var appleSilicon = system.sysctl('hw.optional.arm64') == 1;
  if (rokid.arch === 'x64' && appleSilicon) {
    return rokidRefuse('This is the Intel package — download the Apple silicon one');
  }
  if (rokid.arch === 'arm64' && !appleSilicon) {
    return rokidRefuse('This is the Apple silicon package — download the Intel one');
  }
  var installed = system.files.plistAtPath(rokid.installedVersion);
  if (installed && installed.version && rokidCompareVersions(installed.version, rokid.version) > 0) {
    return rokidRefuse('A newer Rokid Coder is installed (' + installed.version + ') — this package is ' + rokid.version + '; download the latest one');
  }
  return true;
}

function rokidVolumeCheck() {
  if (my.target.availableKilobytes < 300 * 1024) {
    my.result.type = 'Fatal';
    my.result.message = 'Rokid Coder needs 300 MB of free disk space — free some space on this disk and try again';
    return false;
  }
  return true;
}
